package com.gamehub.application;
import com.gamehub.domain.*; import com.gamehub.infrastructure.Database; import com.gamehub.infrastructure.UserRepository; import java.security.*; import javax.crypto.SecretKeyFactory; import java.sql.*; import java.util.Base64;
public final class UserService { private final Database db; private final UserRepository users; public UserService(Database db){this.db=db;this.users=new UserRepository(db.connection());}
 public void bootstrap(String username,String password)throws Exception{validate(username,password);if(users.hasUsers())throw new IllegalStateException("Manager already configured");users.insertUser(norm(username),hash(password),"MANAGER",java.time.Instant.now().toString());}
 public User registerCustomer(String username,String password)throws Exception{validate(username,password);String login=norm(username);Connection c=db.connection();c.setAutoCommit(false);try{long id=users.insertUser(login,hash(password),"CUSTOMER",java.time.Instant.now().toString());users.insertCustomer(id,login,null,null,java.time.Instant.now().toString());c.commit();return new User(id,login,Role.CUSTOMER);}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}
 public User registerCustomer(String fullName,String email,String phone,String password)throws Exception{if(fullName==null||fullName.isBlank()||email==null||!email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")||phone==null||!phone.matches("^[+0-9][0-9 ()-]{6,}$"))throw new IllegalArgumentException("Full name, valid email and phone are required");String login=norm(email);validate(login,password);Connection c=db.connection();c.setAutoCommit(false);try{long id=users.insertUser(login,hash(password),"CUSTOMER",java.time.Instant.now().toString());users.insertCustomer(id,fullName.trim(),login,phone.trim(),java.time.Instant.now().toString());c.commit();return new User(id,login,Role.CUSTOMER);}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}
 public User provision(String actorUsername,String password,String username,String temporaryPassword,Role role)throws Exception{User actor=authenticate(actorUsername,password);if(actor==null||actor.role()!=Role.MANAGER)throw new SecurityException("Manager authentication required");if(role==Role.CUSTOMER)throw new IllegalArgumentException("Use customer registration for public accounts");validate(username,temporaryPassword);users.insertUser(norm(username),hash(temporaryPassword),role.name(),java.time.Instant.now().toString());return authenticate(username,temporaryPassword);}
 private static String norm(String s){return s==null?"":s.trim().toLowerCase(java.util.Locale.ROOT);} private static void validate(String u,String p){if(u==null||u.isBlank()||p==null||p.length()<8)throw new IllegalArgumentException("Username and password (8+ characters) are required");}
 public User authenticate(String username,String password)throws SQLException{String login=norm(username),stored=users.passwordHash(login);if(stored==null||!verify(password,stored))return null;return users.findActive(login);}
 private static String hash(String s)throws Exception{byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);return Base64.getEncoder().encodeToString(salt)+":"+Base64.getEncoder().encodeToString(pbkdf(s,salt));} private static boolean verify(String s,String stored){try{String[] x=stored.split(":");return MessageDigest.isEqual(pbkdf(s,Base64.getDecoder().decode(x[0])),Base64.getDecoder().decode(x[1]));}catch(Exception e){return false;}} private static byte[] pbkdf(String s,byte[] salt)throws Exception{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(new javax.crypto.spec.PBEKeySpec(s.toCharArray(),salt,120000,256)).getEncoded();}}
